input.command:
mkdir bootstrap && 
cat > bootstrap/versions.tf <<'EOF'
terraform {
  required_version = ">= 1.10.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}
EOF
cat > bootstrap/variables.tf <<'EOF'
variable "region" {
  type    = string
  default = "eu-north-1"
}
EOF
cat > bootstrap/main.tf <<'EOF'
provider "aws" {
  region = var.region
}

data "aws_caller_identity" "current" {}

locals {
  bucket_name = "reports-tfstate-${data.aws_caller_identity.current.account_id}"
}

resource "aws_s3_bucket" "state" {
  bucket = local.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "expire-old-state-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 90
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

data "aws_iam_policy_document" "state" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}
EOF
cat > bootstrap/outputs.tf <<'EOF'
output "state_bucket" {
  value = aws_s3_bucket.state.id
}

output "region" {
  value = var.region
}
EOF
cat > backend.tf <<'EOF'
# Bucket is created by bootstrap/. Its name is account-specific, so it is supplied at init time:
#   terraform init -backend-config=backend.hcl
terraform {
  backend "s3" {
    key          = "reports/terraform.tfstate"
    region       = "eu-north-1"
    encrypt      = true
    use_lockfile = true
  }
}
EOF
cat > backend.hcl.example <<'EOF'
# Copy to backend.hcl and fill in the `state_bucket` output of bootstrap/.
bucket = "reports-tfstate-123456789012"
EOF
cat > .gitignore <<'EOF'
.terraform/
*.tfstate
*.tfstate.*
backend.hcl
crash.log
EOF
cat > README.md <<'EOF'
# reports

Terraform for the reports bucket and the key the nightly export job uploads with. The job reads
the key from `terraform output`.

State is stored in a versioned, encrypted S3 bucket with native S3 locking (`use_lockfile`,
Terraform >= 1.10), so anyone on the team with access to the bucket can plan and apply. The state
contains the uploader's secret access key, so grant bucket access only to people who may see it.

## One-time setup: create the state bucket

`bootstrap/` creates the bucket. It cannot use the bucket itself, so its own state is local
(`bootstrap/terraform.tfstate`, git-ignored). Run it once, with admin-level credentials:

```sh
cd bootstrap
terraform init
terraform apply
terraform output state_bucket
```

The bucket has `prevent_destroy` set. Keep `bootstrap/terraform.tfstate` somewhere safe; if it is
lost the bucket can be re-imported with `terraform import aws_s3_bucket.state <bucket-name>`.

Team members need `s3:ListBucket` on the bucket and `s3:GetObject`, `s3:PutObject` and
`s3:DeleteObject` on `reports/*` (the lock file is `reports/terraform.tfstate.tflock`).

## Daily workflow

```sh
cp backend.hcl.example backend.hcl   # set bucket to the state_bucket output (once per checkout)
terraform init -backend-config=backend.hcl
terraform plan
terraform apply
```

If a run is interrupted and leaves a stale lock, use `terraform force-unlock <id>`.

## Migrating the existing local state (once)

The person holding the current `terraform.tfstate` runs, after the bootstrap step:

```sh
terraform init -backend-config=backend.hcl -migrate-state
terraform plan   # should show no changes
```

Answer `yes` to copy the state to S3. Then delete the local `terraform.tfstate*` files
(keep a copy until the plan is clean). Everyone else just follows the daily workflow.
EOF
which terraform && (cd bootstrap && terraform init -backend=false >/dev/null && terraform validate; cd .. && terraform init -backend=false >/dev/null && terraform validate; terraform fmt -check -recursive); git status --short

